from __future__ import annotations

from pathlib import Path
import csv, html, json, os, re, shutil, sys
from urllib.parse import unquote, urlparse
from task1_localization import sport_display, STATUS_DISPLAY, RULE_DISPLAY
from task2_localization import NOC_ZH

ROOT=Path(__file__).resolve().parents[2]
DEL=ROOT/'交付文件'
T1=DEL/'任务一_数据体检'
T2=DEL/'任务二_百年全景'/'05_交互总览'/'index.html'
T3=DEL/'任务三_专题深挖'
T4=DEL/'任务四_开放创作'
PORTAL=DEL/'作品总入口'/'index.html'

def read_csv(path):
    with path.open('r',encoding='utf-8-sig',newline='') as f:
        return list(csv.DictReader(f))

def dump(data):
    return json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')

def link(frm,to):
    return Path(os.path.relpath(to,frm.parent)).as_posix()

def task_one():
    qc=read_csv(T1/'01_报告与说明'/'03_质量检查登记表.csv')
    for x in qc:
        for key in ('检查内容','实测结果','处理决定'):
            x[key]=x[key].replace('Sport','运动').replace('Event','小项').replace('player_id','运动员标识符').replace('ID','标识符').replace('Melbourne','墨尔本').replace('Stockholm','斯德哥尔摩')
    status=read_csv(T1/'99_运行生成'/'event_quality_by_year.csv')
    mapping=read_csv(T1/'99_运行生成'/'sport_mapping.csv')
    compare=read_csv(T1/'04_质量检查结果'/'2024双口径敏感性.csv')
    for x in status: x['Year']=int(x['Year']);x['records']=int(x['records'])
    for x in status:x['event_status_zh']=STATUS_DISPLAY[x['event_status']]
    for x in mapping:
        x['Sport_zh']=sport_display(x['Sport'])
        x['sport_family_zh']=sport_display(x['sport_family'])
        x['rule_zh']=RULE_DISPLAY[x['rule']]
    compare=[{'NOC':x['NOC'],'delegation':NOC_ZH[x['NOC']],'official':int(x['published_rank']),'athlete':int(x['gold_row_rank']),'difference':int(x['gold_row_rank'])-int(x['published_rank'])} for x in compare]
    report=link(T1/'index.html',T1/'01_报告与说明'/'任务一_数据质量与口径说明书.pdf')
    output=link(T1/'index.html',T1/'02_交付数据'/'2024官方329小项奖牌表.csv')
    raw=dump({'qc':qc,'status':status,'mapping':mapping,'compare':compare})
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>任务一｜奥运数据体检室</title></head><body><header class="xz-hero"><div class="xz-eyebrow">01 / 数据基础</div><h1>先把数据<br><em>说清楚</em></h1><p class="xz-lead">一份可信的奥运故事，从统计单位、字段漂移和特殊历史记录开始。这里可以逐项检查质量决定，也能看到不同口径如何改变排名。</p><div class="xz-hero-actions"><a class="xz-primary" href="{report}">阅读质量说明书 ↗</a><a class="xz-secondary" href="{output}">下载官方小项表 ↓</a></div></header><main class="xz-container"><section class="xz-section"><div class="xz-section-top"><span>数据审计 / 01</span><h2>每一条处理决定，都能追溯</h2></div><div class="xz-kpis"><article><strong>{len(qc)}</strong><span>项可复现检查</span></article><article><strong>{len(mapping)}</strong><span>条体育大类映射</span></article><article><strong>329</strong><span>项2024官方获奖小项</span></article><article><strong>2</strong><span>套核心奖牌口径</span></article></div><div class="xz-toolbar"><label>搜索质量检查或处理决定 <input id="qc-search" type="search" placeholder="例如：重复、缺失、Event"></label><span id="qc-count" aria-live="polite"></span></div><div id="qc-list" class="xz-qc"></div></section><section class="xz-section" id="年份"><div class="xz-section-top"><span>质量轨迹 / 02</span><h2>Event 字段从何时开始变得模糊？</h2><p>选择年份查看原始记录的 Event 标签状态。图中是运动员行数，不代表奖牌小项数。</p></div><div class="xz-toolbar"><label>届次 <select id="year"></select></label><div class="xz-segment" id="year-quick"><button data-year="2016">2016</button><button data-year="2020">2020</button><button data-year="2024">2024</button></div></div><div id="status-bars" class="xz-status"></div></section><section class="xz-section" id="口径"><div class="xz-section-top"><span>统计口径 / 03</span><h2>同一届奥运，可以排出不同名次</h2><p>2024官方小项排名与运动员行排名的差异。团队项目只授予一枚小项奖牌，但会产生多条运动员获奖记录。</p></div><div class="xz-toolbar"><label>查找代表团 <input id="noc-search" type="search" placeholder="输入代码或英文名称"></label><label>排序 <select id="rank-sort"><option value="change">按名次变化</option><option value="official">按官方排名</option><option value="athlete">按运动员行排名</option></select></label></div><div class="xz-table-scroll"><table><thead><tr><th>代表团</th><th>官方名次</th><th>运动员行名次</th><th>名次差</th></tr></thead><tbody id="rank-body"></tbody></table></div></section><section class="xz-section" id="映射"><div class="xz-section-top"><span>字段归一 / 04</span><h2>项目名称漂移，如何回到同一大类？</h2><p>搜索原始 Sport 字段，核对归一结果和处理规则。逗号拼接的复合标签也列在映射表中。</p></div><div class="xz-toolbar"><label>搜索原始或归一名称 <input id="sport-search" type="search" placeholder="例如：Basketball"></label><span id="sport-count" aria-live="polite"></span></div><div class="xz-table-scroll"><table><thead><tr><th>原始名称</th><th>归一大类</th><th>规则</th></tr></thead><tbody id="sport-body"></tbody></table></div></section><section class="xz-section xz-note"><span>特殊记录 / 05</span><h2>边界条件明确记录</h2><div class="xz-note-grid"><p><b>1906届</b>采用排除为主、纳入为敏感性检验的双轨口径。</p><p><b>1956双城</b>按同一届次处理，保留举办城市差异。</p><p><b>政体与身份</b>遵循当届 NOC，不擅自合并历史政体；ROC、AIN、EOR 独立标记。</p></div><a href="{report}">查看全部规则与代码 →</a></section></main><script>const D={raw};const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));function qc(){{let q=$('#qc-search').value.toLowerCase(),a=D.qc.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));$('#qc-count').textContent=`显示 ${{a.length}} / ${{D.qc.length}} 项`;$('#qc-list').innerHTML=a.map((x,i)=>`<details><summary><span class="xz-qcid">${{esc(x['编号']||x['检查编号']||String(i+1).padStart(2,'0'))}}</span><b>${{esc(Object.values(x)[1])}}</b><span>查看决定 ↗</span></summary><div>${{Object.entries(x).slice(2).map(([k,v])=>`<p><small>${{esc(k)}}</small><strong>${{esc(v)}}</strong></p>`).join('')}}</div></details>`).join('')}}$('#qc-search').oninput=qc;qc();const ys=[...new Set(D.status.map(x=>x.Year))].sort((a,b)=>b-a);$('#year').innerHTML=ys.map(y=>`<option>${{y}}</option>`).join('');$('#year').value='2024';function yr(){{let a=D.status.filter(x=>x.Year===+$('#year').value),max=Math.max(1,...a.map(x=>x.records));$('#status-bars').innerHTML=a.map(x=>`<div class="xz-stat-row"><span>${{esc(x.event_status.replaceAll('_',' '))}}</span><div><i style="width:${{x.records/max*100}}%"></i></div><b>${{x.records.toLocaleString()}}</b></div>`).join('');document.querySelectorAll('#year-quick button').forEach(b=>b.classList.toggle('active',b.dataset.year===$('#year').value))}}$('#year').onchange=yr;document.querySelectorAll('#year-quick button').forEach(b=>b.onclick=()=>{{$('#year').value=b.dataset.year;yr()}});yr();function ranks(){{let q=$('#noc-search').value.toLowerCase(),mode=$('#rank-sort').value,a=D.compare.filter(x=>(x.NOC+' '+x.delegation).toLowerCase().includes(q));a.sort((x,y)=>mode==='change'?Math.abs(y.difference)-Math.abs(x.difference):x[mode]-y[mode]);$('#rank-body').innerHTML=a.slice(0,40).map(x=>`<tr><td><b>${{esc(x.NOC)}}</b><small>${{esc(x.delegation)}}</small></td><td>${{x.official}}</td><td>${{x.athlete}}</td><td><span class="xz-delta">${{x.difference>0?'+':''}}${{x.difference}}</span></td></tr>`).join('')}}$('#noc-search').oninput=ranks;$('#rank-sort').onchange=ranks;ranks();function sports(){{let q=$('#sport-search').value.toLowerCase(),a=D.mapping.filter(x=>(x.Sport+' '+x.sport_family).toLowerCase().includes(q));$('#sport-count').textContent=`显示 ${{Math.min(40,a.length)}} / ${{a.length}} 条`;$('#sport-body').innerHTML=a.slice(0,40).map(x=>`<tr><td>${{esc(x.Sport)}}</td><td><b>${{esc(x.sport_family)}}</b></td><td>${{esc(x.rule)}}</td></tr>`).join('')}}$('#sport-search').oninput=sports;sports();</script></body></html>'''
    page=page.replace('例如：重复、缺失、Event','例如：重复、缺失、小项')
    page=page.replace('Event 字段从何时开始变得模糊？','小项名称从何时开始变得模糊？')
    page=page.replace('原始记录的 Event 标签状态','原始记录的小项标签状态')
    page=page.replace('输入代码或英文名称','输入中文名称或代表团代码')
    page=page.replace('搜索原始 Sport 字段','搜索原始运动名称')
    page=page.replace('例如：Basketball','例如：篮球')
    page=page.replace('遵循当届 NOC，不擅自合并历史政体；ROC、AIN、EOR 独立标记。','遵循当届代表团身份，不擅自合并历史政体；俄罗斯奥委会、个人中立运动员、难民代表队独立标记。')
    page=page.replace("esc(x.event_status.replaceAll('_',' '))",'esc(x.event_status_zh)')
    page=page.replace('<b>${esc(x.NOC)}</b><small>${esc(x.delegation)}</small>','<b title="${esc(x.NOC)}">${esc(x.delegation)}</b>')
    page=page.replace("(x.Sport+' '+x.sport_family).toLowerCase().includes(q)","(x.Sport+' '+x.sport_family+' '+x.Sport_zh+' '+x.sport_family_zh+' '+x.rule_zh).toLowerCase().includes(q)")
    page=page.replace('<td>${esc(x.Sport)}</td><td><b>${esc(x.sport_family)}</b></td><td>${esc(x.rule)}</td>','<td title="${esc(x.Sport)}">${esc(x.Sport_zh)}</td><td title="${esc(x.sport_family)}"><b>${esc(x.sport_family_zh)}</b></td><td>${esc(x.rule_zh)}</td>')
    old=".join('')}$('#qc-search').oninput=qc"
    new=".join('');const cards=[...$('#qc-list').children],mid=Math.ceil(cards.length/2),left=document.createElement('div'),right=document.createElement('div');left.className=right.className='xz-qc-col';left.append(...cards.slice(0,mid));right.append(...cards.slice(mid));$('#qc-list').append(left,right)}$('#qc-search').oninput=qc"
    assert old in page
    page=page.replace(old,new,1)
    page=page.replace('</head>','<style id="qc-independent-columns">#qc-list{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}#qc-list .xz-qc-col{display:flex;flex-direction:column;gap:12px}@media(max-width:640px){#qc-list{grid-template-columns:1fr}}</style></head>',1)
    (T1/'index.html').write_text(page,encoding='utf-8')

