def page_interactions(page,path):
    page=re.sub(r'<section id="xz-model-compare".*?</section>','',page,flags=re.S)
    page=re.sub(r'<div id="xz-extra-controls".*?</div>','',page,flags=re.S)
    page=re.sub(r'<script id="xz-page-extras">.*?</script>','',page,flags=re.S)
    if path==T2:
        page=page.replace('<script id="xz-page-extras">','<div id="xz-extra-controls"><button type="button" id="xz-reset">重置筛选 ↺</button><span id="xz-active-filters" aria-live="polite"></span></div><script id="xz-page-extras">',1) if '<script id="xz-page-extras">' in page else page.replace('</body>','<div id="xz-extra-controls"><button type="button" id="xz-reset">重置筛选 ↺</button><span id="xz-active-filters" aria-live="polite"></span></div></body>',1)
        extra='''<script id="xz-page-extras">(()=>{const ids=['year','noc','sex','sport','metric'],f=ids.map(x=>document.getElementById(x));const status=document.getElementById('xz-active-filters');const update=()=>status.textContent=`当前启用 ${f.filter(x=>x.selectedIndex>0).length} 项筛选`;f.forEach(x=>x.addEventListener('change',update));document.getElementById('xz-reset').onclick=()=>{f.forEach(x=>{x.selectedIndex=0;x.dispatchEvent(new Event('change',{bubbles:true}))});update()};update()})();</script>'''
    elif path==T3/'S2_口径的魔力'/'06_交互榜'/'index.html':
        page=page.replace('</div><section class="cards">','<div id="xz-extra-controls"><label>搜索代表团 <input id="xz-noc-filter" type="search" placeholder="输入 NOC 代码"></label><span id="xz-filter-count" aria-live="polite"></span></div></div><section class="cards">',1)
        extra='''<script id="xz-page-extras">(()=>{const input=document.querySelector('#xz-noc-filter'),tbody=document.querySelector('#body'),count=document.querySelector('#xz-filter-count');function apply(){const q=input.value.trim().toUpperCase();let n=0;tbody.querySelectorAll('tr').forEach(r=>{const ok=r.textContent.toUpperCase().includes(q);r.hidden=!ok;if(ok)n++});count.textContent=`显示 ${n} 个代表团`}input.addEventListener('input',apply);new MutationObserver(apply).observe(tbody,{childList:true});apply()})();</script>'''
    elif path==T3/'S3_冠军的保质期'/'06_冠军王朝时间轴'/'index.html':
        page=page.replace('</select></div><div class="轴"','</select><div id="xz-extra-controls"><button type="button" id="xz-surprise">随机探索一个王朝 ↗</button></div></div><div class="轴"',1)
        extra='''<script id="xz-page-extras">(()=>{const b=document.querySelector('#xz-surprise'),s=document.querySelector('#代表团');if(b&&s)b.onclick=()=>{const a=[...s.options].filter(x=>x.value&&!x.value.includes('全部'));if(a.length){s.value=a[Math.floor(Math.random()*a.length)].value;s.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('main').scrollIntoView({behavior:'smooth'})}}})();</script>'''
    elif path==T4/'01_交互式Dashboard'/'index.html':
        csv_path=T4/'02_2028洛杉矶预测'/'LA2028机器学习集成预测榜.csv'
        rows=read_csv(csv_path)
        assert {x['NOC'] for x in rows} <= NOC_ZH.keys(), '预测榜存在未翻译的代表团'
        model=[{'NOC':x['NOC'],'base':round(float(x['forecast_total_programme']),1),'ensemble':round(float(x['ensemble_total']),1),'rank':int(x['ensemble_rank'])} for x in rows]
        section='''<section id="xz-model-compare" class="xz-model"><div class="xz-section-top"><span>模型对照 / 2028</span><h2>让两种预测同屏</h2><p>切换透明历史基线与项目级集成预测，观察代表团点估计的变化。这里不把基线区间直接当作集成模型区间。</p></div><div class="xz-toolbar"><label>选择模型 <select id="xz-model"><option value="ensemble">项目级集成预测</option><option value="base">透明历史基线</option></select></label><label>搜索代表团 <input id="xz-model-search" type="search" placeholder="如 中国、美国"></label><span id="xz-model-count" aria-live="polite"></span></div><div id="xz-model-bars" class="xz-model-bars"></div></section>'''
        page=page.replace('</main>',section+'</main>',1)
        extra=f'''<script id="xz-page-extras">(()=>{{const D={dump(model)},mode=document.querySelector('#xz-model'),search=document.querySelector('#xz-model-search'),box=document.querySelector('#xz-model-bars'),count=document.querySelector('#xz-model-count');function draw(){{const key=mode.value,q=search.value.trim().toUpperCase(),a=D.filter(x=>(x.NOC+' '+displayNoc(x.NOC)).toUpperCase().includes(q)).sort((x,y)=>y[key]-x[key]).slice(0,q?30:20),max=Math.max(1,...a.map(x=>x[key]));count.textContent=`显示 ${{a.length}} 个代表团`;box.innerHTML=a.map((x,i)=>`<div class="xz-model-row"><b>${{i+1}}</b><strong title="${{x.NOC}}">${{displayNoc(x.NOC)}}</strong><div class="xz-model-track"><i style="width:${{x[key]/max*100}}%"></i></div><b>${{x[key].toFixed(1)}}</b><small>集成与基线差 ${{(x.ensemble-x.base)>=0?'+':''}}${{(x.ensemble-x.base).toFixed(1)}}</small></div>`).join('')||'<p>没有匹配的代表团。</p>'}}mode.onchange=draw;search.oninput=draw;draw()}})();</script>'''
    else:return page
    if '</body>' in page:page=page.replace('</body>',extra+'</body>',1)
    else:page+=extra
    return page

def enhance(page,path):
    if path==T4/'03_数据新闻'/'index.html':
        page=page.replace('../02_2028洛杉矶预测/预测方法与验证方案.md','../02_2028洛杉矶预测/index.html')
    if path==T4/'01_交互式Dashboard'/'index.html':
        if 'const displayNoc=' not in page:
            names={k:NOC_ZH[k] for k in {x['NOC'] for x in read_csv(T4/'02_2028洛杉矶预测'/'LA2028奖牌预测完整榜.csv')}}
            page=page.replace('const 数据=',f'const nocZh={dump(names)};const displayNoc=k=>nocZh[k]||k;const 数据=',1)
        page=page.replace('x.NOC.includes(搜索.value.toUpperCase())',"(x.NOC+' '+displayNoc(x.NOC)).toUpperCase().includes(搜索.value.trim().toUpperCase())")
        page=page.replace('<b>${x.NOC}</b>','<b title="${x.NOC}">${displayNoc(x.NOC)}</b>')
        page=page.replace('placeholder="搜索代表团代码"','placeholder="搜索中文名称或代码"')
    page=page_interactions(page,path)
    page=re.sub(r'<style id="xz-ui">.*?</style>','',page,flags=re.S)
    page=re.sub(r'<style id="xz-motion-style">.*?</style>','',page,flags=re.S)
    page=re.sub(r'<style id="xz-dashboard-local">.*?</style>','',page,flags=re.S)
    page=re.sub(r'<nav id="xz-nav".*?<button type="button" id="xz-top".*?</button>','',page,flags=re.S)
    page=re.sub(r'<script id="xz-ui-script">.*?</script>','',page,flags=re.S)
    page=re.sub(r'<script id="xz-motion-script">.*?</script>','',page,flags=re.S)
    current=next((i for i,part in enumerate(path.parts) if part.startswith('任务') and '_' in part),None)
    rootlinks=[T1/'index.html',T2,T3/'统一中文入口'/'index.html',T4/'index.html']
    nav=NAV.replace('__HOME__',link(path,ROOT/'index.html')).replace('__OVERVIEW__',link(path,PORTAL))
    for placeholder,dest in zip(['__ONE__','__TWO__','__THREE__','__FOUR__'],rootlinks): nav=nav.replace(placeholder,link(path,dest))
    group=next((x for x in path.parts if x.startswith('任务') and '_' in x),'')
    for i,stem in enumerate(['任务一','任务二','任务三','任务四'],1):nav=nav.replace(f'__CURRENT{i}__','aria-current="page"' if group.startswith(stem) else '')
    themed=CSS.replace('</style>','body{padding-top:68px} @media(max-width:900px){body{padding-top:60px}} '+EXTRA_CSS+PREMIUM_CSS+'</style>')+MOTION_CSS+(DASH_CSS if path==T4/'01_交互式Dashboard'/'index.html' else '')
    if '</head>' in page:page=page.replace('</head>',themed+'</head>',1)
    elif '<main' in page:page=page.replace('<main',themed+'<main',1)
    if '<body>' in page:page=page.replace('<body>','<body>'+nav,1)
    elif '<main' in page:page=page.replace('<main',nav+'<main',1)
    if '</body>' in page:page=page.replace('</body>',JS+MOTION_JS+'</body>',1)
    else:page+=JS+MOTION_JS
    return page

def sync_site(pages):
    site=ROOT/'项目工作区'/'sites'/'la28-fullscore'
    manifest=site/'.openai'/'hosting.json'
    if not manifest.exists():return
    dist=site/'dist';dist.mkdir(parents=True,exist_ok=True)
    targets=set(pages)
    for path in pages:
        page=path.read_text(encoding='utf-8')
        for raw in re.findall(r'(?:href|src)=["\']([^"\']+)["\']',page):
            u=urlparse(raw)
            if u.scheme or raw.startswith(('#','//')):continue
            target=(path.parent/unquote(u.path)).resolve()
            if target.is_file() and target.is_relative_to(DEL.resolve()):targets.add(target)
    for source in targets:
        target=dist/source.relative_to(DEL);target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(source,target)
    (dist/'index.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=作品总入口/index.html"><title>晓组织｜奥运数据观察</title><a href="作品总入口/index.html">进入作品</a></html>',encoding='utf-8')

def main():
    task_one();overview();task_four_portal()
    pages=[PORTAL,T1/'index.html',T2,T3/'统一中文入口'/'index.html',T3/'S1_东道主效应'/'index.html',T3/'S2_口径的魔力'/'06_交互榜'/'index.html',T3/'S2_口径的魔力'/'06_滚动叙事专题'/'index.html',T3/'S2_口径的魔力'/'07_口径实验室'/'index.html',T3/'S3_冠军的保质期'/'06_冠军王朝时间轴'/'index.html',T3/'S3_冠军的保质期'/'07_王朝生存图'/'index.html',T4/'index.html',T4/'01_交互式Dashboard'/'index.html',T4/'02_2028洛杉矶预测'/'index.html',T4/'03_数据新闻'/'index.html',T4/'06_赛后验收单'/'index.html',T4/'交互看板'/'index.html']
    for path in pages:
        if path.exists():path.write_text(enhance(path.read_text(encoding='utf-8'),path),encoding='utf-8')
    sync_site(pages)
    print(json.dumps({'pages':len(pages),'task1':str(T1/'index.html'),'overview':str(PORTAL)},ensure_ascii=False))

if __name__=='__main__':main()


